func (this *Control) WidgetStyle() int32 {
	return this.impl.widgetStyle_()
}

func (this *Control) widgetStyle_() int32 {
	var bits int32 = win32.OSWS_CHILD | win32.OSWS_VISIBLE | win32.OSWS_CLIPSIBLINGS
	if this.impl.isUseWsBorder_() {
		if (this.style & BORDER) != 0 {
			bits |= win32.OSWS_BORDER
		}
	}
	return bits
}
